@Component("externalAccount-handler")
@ProcessingGroup("externalAccount-processing-group")
public class ExternalAccountEventHandler {
	
	// core constructor
	ExternalAccountEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateExternalAccountEvent
     */
    @EventHandler
    public void handle( CreateExternalAccountEvent event) {
        entityManager.persist(new ExternalAccount(event.getExternalAccountId(), event.getName(), event.getIban(), event.getAccountNumber(), event.getBic(), event.getBankName(), event.getCountry(), event.getCustomer(), event.getTransactions()));
    }

    /*
     * @param	event UpdateExternalAccountEvent
     */
    @EventHandler
    public ExternalAccount handle( UpdateExternalAccountEvent event) {
    	entityManager.merge(new ExternalAccount(event.getExternalAccountId(), event.getName(), event.getIban(), event.getAccountNumber(), event.getBic(), event.getBankName(), event.getCountry(), event.getCustomer(), event.getTransactions()));
    }
    
    /*
     * @param	event DeleteExternalAccountEvent
     */
    @EventHandler
    public void on( DeleteExternalAccountEvent event) {
    	ExternalAccount entity = new ExternalAccount();
   
    	// ------------------------------------------
    	// apply the ExternalAccountId
    	// ------------------------------------------
    	entity.setExternalAccountId( event.getExternalAccountId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ExternalAccountRepository externalAccountEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ExternalAccountEventHandler.class.getName());

}
